import{_ as t,o as a,c as n,a4 as r}from"./chunks/framework.CzJ_HCFe.js";const u=JSON.parse('{"title":"Rise/set convention research and solar decision (#177)","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0005-rise-set-convention.md","filePath":"decisions/0005-rise-set-convention.md","lastUpdated":1789991296000}'),o={name:"decisions/0005-rise-set-convention.md"};function i(s,e,d,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="rise-set-convention-research-and-solar-decision-177" tabindex="-1">Rise/set convention research and solar decision (#177) <a class="header-anchor" href="#rise-set-convention-research-and-solar-decision-177" aria-label="Permalink to &quot;Rise/set convention research and solar decision (#177)&quot;">​</a></h1><p>Date: 2026-09-19. Decision: retain the existing astronomical upper-limb, atmospheric-refraction convention for the product&#39;s Drik Panchang comparison target. No frozen calculation code or published timing changes.</p><h2 id="evidence-and-scope" tabindex="-1">Evidence and scope <a class="header-anchor" href="#evidence-and-scope" aria-label="Permalink to &quot;Evidence and scope&quot;">​</a></h2><p><a href="https://www.drikpanchang.com/panchang/sunrise/panchang-sunrise.html" target="_blank" rel="noreferrer">Drik Panchang&#39;s own definition</a> identifies its default as the upper edge with refraction; elevation is disabled by default. <a href="https://www.astro.com/swisseph/swephprg.htm" target="_blank" rel="noreferrer">Swiss Ephemeris</a>, sections 8.12 and 8.12.1, distinguishes that default from <code>BIT_HINDU_RISING</code> (disc centre, no refraction, geocentric, without ecliptic latitude). The latter is a different convention, not a universal requirement for every Panchangam product.</p><p>Four independently revisited rendered day pages cover Hyderabad on January 1 and March 13, and New York on January 1 and May 4, 2026. New York includes standard and daylight-saving time. The minute-precision values and exact URLs are in <code>tests/fixtures/rise_set_convention_oracle.json</code>.</p><table tabindex="0"><thead><tr><th>City/date</th><th>Published rise/set</th><th>Current rise/set</th><th>Alternate Hindu rise/set</th></tr></thead><tbody><tr><td>Hyderabad 2026-01-01</td><td>06:46 / 17:53</td><td>06:46:10 / 17:52:54</td><td>06:49:58 / 17:49:06</td></tr><tr><td>Hyderabad 2026-03-13</td><td>06:26 / 18:26</td><td>06:25:53 / 18:25:25</td><td>06:29:21 / 18:21:57</td></tr><tr><td>New York 2026-01-01</td><td>07:20 / 16:39</td><td>07:20:06 / 16:39:24</td><td>07:25:11 / 16:34:19</td></tr><tr><td>New York 2026-05-04</td><td>05:51 / 19:55</td><td>05:50:53 / 19:55:18</td><td>05:55:32 / 19:50:37</td></tr></tbody></table><p>Current maximum absolute difference is 35 seconds across these eight points; the test allows 120 seconds because published times have minute precision and the repository and source city coordinates differ. This is a solar comparison, not an all-location certification.</p><h2 id="moon-comparison-a-separate-correction-remains-open" tabindex="-1">Moon comparison: a separate correction remains open <a class="header-anchor" href="#moon-comparison-a-separate-correction-remains-open" aria-label="Permalink to &quot;Moon comparison: a separate correction remains open&quot;">​</a></h2><p>The same four rendered day pages were separately inspected for their Moon events, including explicit next-day suffixes. The source&#39;s solar definition must not be assumed to describe its Moon calculation. These eight labeled Moon events differ from the current default by 231–381 seconds. A controlled Swiss comparison using <code>BIT_DISC_CENTER | BIT_NO_REFRACTION</code>, retaining topocentric position and lunar ecliptic latitude, agrees within 33 seconds.</p><table tabindex="0"><thead><tr><th>Page city/date</th><th>Published Moon rise/set</th><th>Current default</th><th>Disc centre, no refraction</th></tr></thead><tbody><tr><td>Hyderabad 2026-01-01</td><td>15:43 / 05:26 Jan 2</td><td>15:38:57 / 05:29:51 Jan 2</td><td>15:43:07 / 05:25:38 Jan 2</td></tr><tr><td>Hyderabad 2026-03-13</td><td>03:02 Mar 14 / 13:13</td><td>02:57:56 Mar 14 / 13:17:17</td><td>03:01:53 Mar 14 / 13:13:17</td></tr><tr><td>New York 2026-01-01</td><td>14:39 / 06:47 Jan 2</td><td>14:32:39 / 06:52:48 Jan 2</td><td>14:38:27 / 06:46:57 Jan 2</td></tr><tr><td>New York 2026-05-04</td><td>23:24 / 07:03</td><td>23:18:25 / 07:08:34</td><td>23:24:05 / 07:03:01</td></tr></tbody></table><p>This is an empirical candidate convention, not a claim that Drik Panchang publishes its internal lunar flags. Applying the full <code>BIT_HINDU_RISING</code> combination instead also changes parallax and ecliptic-latitude treatment; it differs by as much as 32 minutes 16 seconds in these samples. The Swiss section 8.12.1 Hindu discussion is specifically about the Sun.</p><p><code>tests/fixtures/moon_rise_set_convention_oracle.json</code> and <code>tests/test_moon_rise_set_convention.py</code> preserve the independent values and reproduce all three mode comparisons. They search from midnight of each <strong>printed event&#39;s civil date</strong>. A Panchang page may select a next-day event before sunrise, whereas the current engine starts its Moon search at the requested civil midnight. This fixture does not certify that day-assignment policy or silently change it.</p><p>Keep #177 open for an owner-reviewed lunar convention decision and frozen-core correction. All three engines consume the shared Moon helpers; Moonrise also determines Sankashti&#39;s deciding instant. A future patch must review boundary date impacts, the protected helper-flag assertions and generated calendar corpus, then receive explicit approval and a versioned release. Moonset has no festival caller. Eclipse visibility uses a separate altitude calculation and must not be conflated with this change.</p><h2 id="observer-and-error-experiments" tabindex="-1">Observer and error experiments <a class="header-anchor" href="#observer-and-error-experiments" aria-label="Permalink to &quot;Observer and error experiments&quot;">​</a></h2><p>Swiss Ephemeris 2.10.03 tests retain the existing fixed 1013.25 hPa, 15 C, zero-altitude input policy. Hyderabad altitude 531 m alone changes these solar events by less than one second at fixed pressure. Automatic pressure at that altitude changes them by about ten seconds; zero-degree air changes them by about fourteen seconds. These are controlled sensitivity experiments, not proof of actual weather or a general altitude-correction model.</p><p>At Tromso on both solstices, solar rise/set return status <code>-2</code> and a zero placeholder, not a usable instant. An invalid body raises <code>swisseph.Error</code>. The frozen helper ignores status today; polar no-event handling remains unsupported and must not be advertised as solved. The new tests exercise the Swiss contract directly rather than pinning the helper&#39;s unsafe placeholder as correct behavior. A future guard requires explicit frozen-core approval.</p><h2 id="verification-and-decision-boundary" tabindex="-1">Verification and decision boundary <a class="header-anchor" href="#verification-and-decision-boundary" aria-label="Permalink to &quot;Verification and decision boundary&quot;">​</a></h2><p>Run <code>python -m pytest tests/test_rise_set_convention.py</code> to reproduce the oracle, alternative-mode, atmosphere and status experiments without a network request. The fixture records independent source values; expected values are not generated from the implementation. No PyPI bump is needed for this research-only change. Keep the broad provenance claim <code>partially_verified</code>: the solar default is decided, while the lunar discrepancy and polar output safety remain unresolved.</p>',18)])])}const m=t(o,[["render",i]]);export{u as __pageData,m as default};
